{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/vehicle.gd","contents":"extends VehicleBody3D

const STEER_SPEED = 1.5
const STEER_LIMIT = 0.4
const BRAKE_STRENGTH = 2.0

@export var engine_force_value := 40.0

var turbometer: Range
var turbo_animator: AnimationPlayer

var previous_speed := linear_velocity.length()
var turbo_active := false
var headlights_active := false
var _steer_target := 0.0
var is_compatibility := RenderingServer.get_current_rendering_method() == "gl_compatibility"

@onready var desired_engine_pitch: float = $EngineSound.pitch_scale


func _ready() -> void:
	assert(turbometer)
	assert(turbo_animator)


func _physics_process(delta: float) -> void:
	_steer_target = Input.get_axis(&"turn_right", &"turn_left")
	_steer_target *= STEER_LIMIT

	# Engine sound simulation (not realistic, as this car script has no notion of gear or engine RPM).
	desired_engine_pitch = 0.05 + linear_velocity.length() / (engine_force_value * 0.5)
	# Change pitch smoothly to avoid abrupt change on collision.
	$EngineSound.pitch_scale = lerpf($EngineSound.pitch_scale, desired_engine_pitch, 0.2)

	if absf(linear_velocity.length() - previous_speed) > 1.0:
		# Sudden velocity change, likely due to a collision. Play an impact sound to give audible feedback,
		# and vibrate for haptic feedback.
		$ImpactSound.play()
		Input.vibrate_handheld(100)
		for joypad in Input.get_connected_joypads():
			Input.start_joy_vibration(joypad, 0.0, 0.5, 0.1)

	var turbo_pressed := Input.is_action_pressed(&"boost")
	var new_turbo_active := turbo_pressed and turbometer.value > 0
	if new_turbo_active != turbo_active:
		turbo_animator.play(&"TURBO" if new_turbo_active else &"Idle")

	turbo_active = new_turbo_active
	if turbo_active:
		turbometer.value -= delta * 3.0
	elif not turbo_pressed:
		turbometer.value += delta

	if turbo_active:
		constant_force = global_transform.basis.z * 400.0
	else:
		constant_force = Vector3()

	# Automatically accelerate when using touch controls (reversing overrides acceleration).
	if DisplayServer.is_touchscreen_available() or Input.is_action_pressed(&"accelerate"):
		# Increase engine force at low speeds to make the initial acceleration faster.
		var speed := linear_velocity.length()
		if speed < 5.0 and not is_zero_approx(speed):
			engine_force = clampf(engine_force_value * 5.0 / speed, 0.0, 100.0)
		else:
			engine_force = engine_force_value

		if not DisplayServer.is_touchscreen_available():
			# Apply analog throttle factor for more subtle acceleration if not fully holding down the trigger.
			engine_force *= Input.get_action_strength(&"accelerate")
	else:
		engine_force = 0.0

	if Input.is_action_pressed(&"reverse"):
		# Increase engine force at low speeds to make the initial reversing faster.
		var speed := linear_velocity.length()
		if speed < 5.0 and not is_zero_approx(speed):
			engine_force = -clampf(engine_force_value * 5.0 / speed, 0.0, 100.0)
		else:
			engine_force = -engine_force_value

		# Apply analog brake factor for more subtle braking if not fully holding down the trigger.
		engine_force *= Input.get_action_strength(&"reverse")

	steering = move_toward(steering, _steer_target, STEER_SPEED * delta)

	previous_speed = linear_velocity.length()


func _input(p_input_event: InputEvent) -> void:
	if p_input_event.is_action_pressed(&"toggle_headlights"):
		toggle_headlights()

	if p_input_event.is_action_pressed(&"honk"):
		$HonkSound.play()


func toggle_headlights() -> void:
	for node: Light3D in get_tree().get_nodes_in_group(&"headlight"):
		# Consider headlights as being inactive up to this point if their energy was previously 0.
		headlights_active = is_zero_approx(node.light_energy)
		var t := get_tree().create_tween()

		if headlights_active:
			node.visible = true

		var target_energy := 2.0 if headlights_active else 0.0
		if is_compatibility:
			# Decrease light brightness to compensate for sRGB blending in Compatibility
			# (since headlights cast shadows).
			target_energy *= 0.5
		t.tween_property(
				node,
				^"light_energy",
				target_energy,
				0.2
			).set_trans(Tween.TRANS_SINE).set_ease(Tween.EASE_IN_OUT)

		# Hide light node at the end to avoid performance impact when headlights are off
		# (Godot still renders lights with `light_energy == 0.0` otherwise).
		if not headlights_active:
			t.finished.connect(func() -> void:
				node.visible = false
			)
"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/player_camera.gd","contents":"# The main camera that follows the location of the player. It manages
# zooming out when the map button is pressed, and manages the creation
# of a duplicate itself that will live in the minimap viewport, and will follow
# the original's position in the world using a `RemoteTransform2D`.
#
# The camera supports zooming and camera shake.
extends Camera2D

const SHAKE_EXPONENT := 1.8

@export var max_zoom := 5.0
@export var decay_rate := 1.0
@export var shake_offset_multiplier := Vector2(100.0, 100.0)

var shake_amount := 0.0: set = set_shake_amount
var noise_y : float = 0.0

var _start_zoom := zoom
var _start_position := Vector2.ZERO

@onready var remote_map := $RemoteMap
@onready var remote_distort := $RemoteDistort
@onready var tween: Tween
@onready var noise := FastNoiseLite.new()


func _ready() -> void:
	set_physics_process(false)

	Events.map_toggled.connect(_toggle_map)
	Events.explosion_occurred.connect(_on_Events_explosion_occurred)

	randomize()
	noise.seed = randi()
	noise.frequency = 4
	noise.fractal_octaves = 2
	noise.noise_type = FastNoiseLite.TYPE_PERLIN


func _physics_process(delta):
	self.shake_amount -= decay_rate * delta
	noise_y += delta
	shake()


func shake():
	var amount : float = pow(shake_amount, SHAKE_EXPONENT)
	
	if amount == 0:
		return
		
	offset = Vector2(
		shake_offset_multiplier.x * amount * noise.get_noise_2d(noise_y, noise_y / amount),
		shake_offset_multiplier.y * amount * noise.get_noise_2d(noise_y / amount, noise_y)
	)


func set_shake_amount(value):
	shake_amount = clampf(value, 0.0, 1.0)
	set_physics_process(shake_amount != 0.0)


func setup_camera_map(map: MapView) -> void:
	var camera_map := self.duplicate()
	map.register_camera(camera_map)
	remote_map.remote_path = camera_map.get_path()


func setup_distortion_camera() -> void:
	var distort_camera := self.duplicate()
	ObjectRegistry.register_distortion_effect(distort_camera)
	remote_distort.remote_path = distort_camera.get_path()


func _toggle_map(display: bool, duration: float) -> void:
	if tween and tween.is_running:
		tween.kill()
	tween = create_tween()
	if display:
		tween.tween_property(
			self,
			"zoom",
			_start_zoom,
			duration
		).from_current().set_ease(Tween.EASE_OUT_IN).set_trans(Tween.TRANS_LINEAR)
	else:
		_start_position = position
		tween.tween_property(
			self,
			"zoom",
			Vector2(max_zoom, max_zoom),
			duration
		).from_current().set_ease(Tween.EASE_OUT_IN).set_trans(Tween.TRANS_LINEAR)


func _on_Events_explosion_occurred() -> void:
	self.shake_amount += 0.6
"}}

