{"type": "tool_call", "tool": "batch_tool_calls", "arguments": {"calls": [{"tool": "create_gdscript_file", "arguments": {"script_path": "res://scripts/Pathfinder.gd", "contents": "## Finds the path between two points among walkable cells using the AStar pathfinding algorithm.
class_name PathFinder
extends Reference

const DIRECTIONS = [Vector2.LEFT, Vector2.RIGHT, Vector2.UP, Vector2.DOWN]

var _grid: Resource
var _astar := AStar2D.new()


## Initializes the Astar2D object upon creation.
func _init(grid: Grid, walkable_cells: Array) -> void:
	_grid = grid
	var cell_mappings := {}
	for cell in walkable_cells:
		cell_mappings[cell] = _grid.as_index(cell)
	_add_and_connect_points(cell_mappings)


## Returns the path found between `start` and `end` as an array of Vector2 coordinates.
func calculate_point_path(start: Vector2, end: Vector2) -> PoolVector2Array:
	var start_index: int = _grid.as_index(start)
	var end_index: int = _grid.as_index(end)
	if _astar.has_point(start_index) and _astar.has_point(end_index):
		return _astar.get_point_path(start_index, end_index)
	else:
		return PoolVector2Array()


## Adds and connects the walkable cells to the Astar2D object.
func _add_and_connect_points(cell_mappings: Dictionary) -> void:
	for point in cell_mappings:
		_astar.add_point(cell_mappings[point], point)

	for point in cell_mappings:
		for neighbor_index in _find_neighbor_indices(point, cell_mappings):
			_astar.connect_points(cell_mappings[point], neighbor_index)


## Returns an array of the `cell`'s connectable neighbors.
func _find_neighbor_indices(cell: Vector2, cell_mappings: Dictionary) -> Array:
	var out := []
	for direction in DIRECTIONS:
		var neighbor: Vector2 = cell + direction
		if not cell_mappings.has(neighbor):
			continue
		if not _astar.are_points_connected(cell_mappings[cell], cell_mappings[neighbor]):
			out.push_back(cell_mappings[neighbor])
	return out
"}}]}}

{"type": "tool_call", "tool": "batch_tool_calls", "arguments": {"calls": [{"tool": "create_gdscript_file", "arguments": {"script_path": "res://scripts/character.gd", "contents": "extends Node2D


const PathFindAStar = preload("./pathfind_astar.gd")

enum State {
	IDLE,
	FOLLOW,
}

const MASS: float = 10.0
const ARRIVE_DISTANCE: float = 10.0

@export_range(10, 500, 0.1, "or_greater") var speed: float = 200.0

var _state := State.IDLE
var _velocity := Vector2()

var _click_position := Vector2()
var _path := PackedVector2Array()
var _next_point := Vector2()

@onready var _tile_map: PathFindAStar = $"../TileMapLayer"


func _ready() -> void:
	_change_state(State.IDLE)


func _physics_process(_delta: float) -> void:
	if _state != State.FOLLOW:
		return

	var arrived_to_next_point: bool = _move_to(_next_point)
	if arrived_to_next_point:
		_path.remove_at(0)
		if _path.is_empty():
			_change_state(State.IDLE)
			return
		_next_point = _path[0]


func _unhandled_input(input_event: InputEvent) -> void:
	_click_position = get_global_mouse_position()
	if _tile_map.is_point_walkable(_click_position):
		if input_event.is_action_pressed(&"teleport_to", false, true):
			_change_state(State.IDLE)
			global_position = _tile_map.round_local_position(_click_position)
			reset_physics_interpolation()
		elif input_event.is_action_pressed(&"move_to"):
			_change_state(State.FOLLOW)


func _move_to(local_position: Vector2) -> bool:
	var desired_velocity: Vector2 = (local_position - position).normalized() * speed
	var steering: Vector2 = desired_velocity - _velocity
	_velocity += steering / MASS
	position += _velocity * get_physics_process_delta_time()
	rotation = _velocity.angle()
	return position.distance_to(local_position) < ARRIVE_DISTANCE


func _change_state(new_state: State) -> void:
	if new_state == State.IDLE:
		_tile_map.clear_path()
	elif new_state == State.FOLLOW:
		_path = _tile_map.find_path(position, _click_position)
		if _path.size() < 2:
			_change_state(State.IDLE)
			return
		# The index 0 is the starting cell.
		# We don't want the character to move back to it in this example.
		_next_point = _path[1]
	_state = new_state
"}}]}}

{"type": "tool_call", "tool": "batch_tool_calls", "arguments": {"calls": [{"tool": "create_gdscript_file", "arguments": {"script_path": "res://scripts/pathfind_astar.gd", "contents": "extends TileMapLayer

# Atlas coordinates in tile set for start/end tiles.
const TILE_START_POINT = Vector2i(1, 0)
const TILE_END_POINT = Vector2i(2, 0)

const CELL_SIZE = Vector2i(64, 64)
const BASE_LINE_WIDTH: float = 3.0
const DRAW_COLOR = Color.WHITE * Color(1, 1, 1, 0.5)

# The object for pathfinding on 2D grids.
var _astar := AStarGrid2D.new()

var _start_point := Vector2i()
var _end_point := Vector2i()
var _path := PackedVector2Array()

func _ready() -> void:
	# Region should match the size of the playable area plus one (in tiles).
	# In this demo, the playable area is 17×9 tiles, so the rect size is 18×10.
	# Depending on the setup, TileMapLayer's get_used_rect() can also be used.
	_astar.region = Rect2i(0, 0, 18, 10)
	_astar.cell_size = CELL_SIZE
	_astar.offset = CELL_SIZE * 0.5
	_astar.default_compute_heuristic = AStarGrid2D.HEURISTIC_MANHATTAN
	_astar.default_estimate_heuristic = AStarGrid2D.HEURISTIC_MANHATTAN
	_astar.diagonal_mode = AStarGrid2D.DIAGONAL_MODE_NEVER
	_astar.update()

	# Iterate over all cells on the tile map layer and mark them as
	# non-passable.
	for pos in get_used_cells():
		_astar.set_point_solid(pos)
		# To skip cells with certain atlas coordinates you can use:
		# if get_cell_atlas_coords(pos) == Vector2i(42, 23):
		#     ...
		# You can also add a "Custom Data Layer" to the tile set to group
		# tiles and check it here; in the following example using a string:
		# if get_cell_tile_data(pos).get_custom_data("type") == "obstacle":
		#     ...


func _draw() -> void:
	if _path.is_empty():
		return

	var last_point: Vector2 = _path[0]
	for index in range(1, len(_path)):
		var current_point: Vector2 = _path[index]
		draw_line(last_point, current_point, DRAW_COLOR, BASE_LINE_WIDTH, true)
		draw_circle(current_point, BASE_LINE_WIDTH * 2.0, DRAW_COLOR)
		last_point = current_point


func round_local_position(local_position: Vector2i) -> Vector2i:
	return map_to_local(local_to_map(local_position))


func is_point_walkable(local_position: Vector2) -> bool:
	var map_position: Vector2i = local_to_map(local_position)
	if _astar.is_in_boundsv(map_position):
		return not _astar.is_point_solid(map_position)
	return false


func clear_path() -> void:
	if not _path.is_empty():
		_path.clear()
		erase_cell(_start_point)
		erase_cell(_end_point)
		# Queue redraw to clear the lines and circles.
		queue_redraw()


func find_path(local_start_point: Vector2i, local_end_point: Vector2i) -> PackedVector2Array:
	clear_path()

	_start_point = local_to_map(local_start_point)
	_end_point = local_to_map(local_end_point)
	_path = _astar.get_point_path(_start_point, _end_point)

	if not _path.is_empty():
		set_cell(_start_point, 0, TILE_START_POINT)
		set_cell(_end_point, 0, TILE_END_POINT)

	# Redraw the lines and circles from the start to the end point.
	queue_redraw()

	return _path.duplicate()
"}}]}}

{"type": "tool_call", "tool": "batch_tool_calls", "arguments": {"calls": [{"tool": "create_gdscript_file", "arguments": {"script_path": "res://scripts/character.gd", "contents": "extends Marker3D

@export var character_speed := 10.0
@export var show_path: bool = true

var _nav_path_line: Line3D

@onready var _nav_agent := $NavigationAgent3D as NavigationAgent3D

func _ready() -> void:
	_nav_path_line = Line3D.new()
	add_child(_nav_path_line)
	_nav_path_line.set_as_top_level(true)


func _physics_process(delta: float) -> void:
	if _nav_agent.is_navigation_finished():
		return

	var next_position := _nav_agent.get_next_path_position()
	var offset := next_position - global_position
	global_position = global_position.move_toward(next_position, delta * character_speed)

	# Make the robot look at the direction we're traveling.
	# Clamp Y to 0 so the robot only looks left and right, not up/down.
	offset.y = 0
	if not offset.is_zero_approx():
		look_at(global_position + offset, Vector3.UP)


func set_target_position(target_position: Vector3) -> void:
	_nav_agent.set_target_position(target_position)
	# Get a full navigation path with the NavigationServer API.
	if show_path:
		var start_position := global_transform.origin
		var optimize: bool = true
		var navigation_map := get_world_3d().get_navigation_map()
		var path := NavigationServer3D.map_get_path(
				navigation_map,
				start_position,
				target_position,
				optimize
			)
		_nav_path_line.draw_path(path)
"}}]}}

