{"type": "tool_call", "tool": "batch_tool_calls", "arguments": {"calls": [{"tool": "create_gdscript_file", "arguments": {"script_path": "res://scripts/editor_property_control.gd", "contents": "@tool

extends HBoxContainer


signal resource_changed(next_resource: DialogueResource)


const ITEM_NEW: int = 100
const ITEM_QUICK_LOAD: int = 200
const ITEM_LOAD: int = 201
const ITEM_EDIT: int = 300
const ITEM_CLEAR: int = 301
const ITEM_FILESYSTEM: int = 400


var resource: Resource:
	set(next_resource):
		resource = next_resource
		if button:
			button.resource = resource
	get:
		return resource

var quick_selected_file: String = ""

@onready var button: Button = $ResourceButton
@onready var menu_button: Button = $MenuButton
@onready var menu: PopupMenu = $Menu
@onready var quick_open_dialog: ConfirmationDialog = $QuickOpenDialog
@onready var files_list: Control = $QuickOpenDialog/FilesList
@onready var new_dialog: FileDialog = $NewDialog
@onready var open_dialog: FileDialog = $OpenDialog


func _ready() -> void:
	menu_button.icon = get_theme_icon("GuiDropdown", "EditorIcons")


func build_menu() -> void:
	menu.clear()

	menu.add_icon_item(DMPlugin.instance._get_plugin_icon(), "New Dialogue", ITEM_NEW)
	menu.add_separator()
	menu.add_icon_item(get_theme_icon("Load", "EditorIcons"), "Quick Load", ITEM_QUICK_LOAD)
	menu.add_icon_item(get_theme_icon("Load", "EditorIcons"), "Load", ITEM_LOAD)
	if resource:
		menu.add_icon_item(get_theme_icon("Edit", "EditorIcons"), "Edit", ITEM_EDIT)
		menu.add_icon_item(get_theme_icon("Clear", "EditorIcons"), "Clear", ITEM_CLEAR)
		menu.add_separator()
		menu.add_item("Show in FileSystem", ITEM_FILESYSTEM)

	menu.size = Vector2.ZERO


#region Signals


func _on_new_dialog_file_selected(path: String) -> void:
	DMPlugin.instance.main_view.new_file(path)
	if DMCache.has_file(path):
		resource_changed.emit(load(path))
	else:
		var next_resource: DialogueResource = await DMPlugin.instance.import_plugin.compiled_resource
		next_resource.resource_path = path
		resource_changed.emit(next_resource)


func _on_open_dialog_file_selected(file: String) -> void:
	resource_changed.emit(load(file))


func _on_resource_button_pressed() -> void:
	if is_instance_valid(resource):
		DMPlugin.open_file(resource)

	elif menu.visible:
		menu.hide()
	else:
		build_menu()
		@warning_ignore("narrowing_conversion")
		menu.position = get_viewport().position + Vector2i(
			button.global_position.x + button.size.x - menu.size.x,
			2 + menu_button.global_position.y + button.size.y
		)
		menu.popup()


func _on_resource_button_resource_dropped(next_resource: Resource) -> void:
	resource_changed.emit(next_resource)


func _on_menu_button_pressed() -> void:
	if menu.visible:
		menu.hide()
	else:
		build_menu()
		@warning_ignore("narrowing_conversion")
		menu.position = get_viewport().position + Vector2i(
			menu_button.global_position.x + menu_button.size.x - menu.size.x,
			2 + menu_button.global_position.y + menu_button.size.y
		)
		menu.popup()


func _on_menu_id_pressed(id: int) -> void:
	match id:
		ITEM_NEW:
			new_dialog.popup_centered()

		ITEM_QUICK_LOAD:
			quick_selected_file = ""
			files_list.files = DMCache.get_files()
			if resource:
				files_list.select_file(resource.resource_path)
			quick_open_dialog.popup_centered()
			files_list.focus_filter()

		ITEM_LOAD:
			open_dialog.popup_centered()

		ITEM_EDIT:
			DMPlugin.open_file(resource)

		ITEM_CLEAR:
			resource_changed.emit(null)

		ITEM_FILESYSTEM:
			EditorInterface.get_file_system_dock().navigate_to_path(resource.resource_path)


func _on_files_list_file_double_clicked(file_path: String) -> void:
	resource_changed.emit(load(file_path))
	quick_open_dialog.hide()


func _on_files_list_file_selected(file_path: String) -> void:
	quick_selected_file = file_path


func _on_quick_open_dialog_confirmed() -> void:
	if quick_selected_file != "":
		resource_changed.emit(load(quick_selected_file))


#endregion
"}}]}}

{"type": "tool_call", "tool": "batch_tool_calls", "arguments": {"calls": [{"tool": "create_gdscript_file", "arguments": {"script_path": "res://scripts/TowerPlacer.gd", "contents": "# Allows the player to interactively place a tower on the game grid.
# Keeps track of free and occupied cells.
class_name TowerPlacer
extends TileMap

signal tower_placed(tower)

# The ID of the tiles where players can place a tower.
const AVAILABLE_CELL_ID := 0
const INVALID_CELL_ID := 1

onready var _visual_grid := $VisualGrid

var _current_cell := Vector2.ZERO
var _current_tower: Tower


func _ready() -> void:
	set_process_unhandled_input(false)


func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventMouseMotion:
		_snap_tower_to_grid()
	if event.is_action_pressed("tower_placement"):
		_place_tower()


func setup_available_cells(cells_array: PoolVector2Array) -> void:
	for cell in cells_array:
		set_cell_placeable(cell)


func add_new_tower(tower: Tower) -> void:
	if _current_tower:
		_current_tower.queue_free()

	add_child(tower)
	_current_tower = tower

	set_process_unhandled_input(true)
	_visual_grid.visible = true

	_snap_tower_to_grid()


func set_cell_unplaceable(cell: Vector2) -> void:
	set_cellv(cell, INVALID_CELL_ID)


func set_cell_placeable(cell: Vector2) -> void:
	set_cellv(cell, AVAILABLE_CELL_ID)


func is_cell_placeable(cell: Vector2) -> bool:
	return get_cellv(cell) == AVAILABLE_CELL_ID


func _place_tower() -> void:
	set_process_unhandled_input(false)
	_visual_grid.visible = false

	if not is_cell_placeable(_current_cell):
		_current_tower.queue_free()
		_current_tower = null
		return
	set_cell_unplaceable(_current_cell)

	emit_signal("tower_placed", _current_tower)
	_current_tower.connect("sold", self, "_on_Tower_sold")
	_current_tower = null


func _snap_tower_to_grid() -> void:
	_current_cell = world_to_map(get_global_mouse_position())
	_current_tower.global_position = map_to_world(_current_cell)
	if not is_cell_placeable(_current_cell):
		_current_tower.modulate = Color(1, 0.375, 0.375)
	else:
		_current_tower.modulate = Color.white


func _on_Tower_sold(_price: int, place: Vector2) -> void:
	set_cell_placeable(world_to_map(place))
"}}]}}

{"type": "tool_call", "tool": "batch_tool_calls", "arguments": {"calls": [{"tool": "create_gdscript_file", "arguments": {"script_path": "res://scripts/Tower.gd", "contents": "class_name Tower
extends Node2D

signal sold(price, place)
signal selected(selected)

export var cost := 100

onready var _weapon := $Weapon2D
onready var _interface := $Interface
onready var _cooldown_bar := $UICooldownBar
onready var _selection := $SelectableArea2D
onready var _upgrades := $Upgrades


func _ready() -> void:
	_weapon.show_range()
	for upgrade in _upgrades.get_children():
		upgrade.weapon = _weapon
		upgrade.connect("applied", self, "_on_Upgrade_applied")


func show_interface() -> void:
	_weapon.show_range()
	_interface.appear()


func hide_interface() -> void:
	_weapon.hide_range()
	_interface.disappear()


func get_upgrades() -> Array:
	return _upgrades.get_children()


func _on_SelectableArea2D_selection_changed(selected) -> void:
	if selected:
		show_interface()
	else:
		hide_interface()
	emit_signal("selected", selected)


func _on_SellButton_pressed() -> void:
	emit_signal("sold", cost / 2, position)
	queue_free()


func _on_Weapon2D_fired() -> void:
	_cooldown_bar.start(_weapon.fire_cooldown)


func _on_Upgrade_applied(upgrade_cost: int) -> void:
	cost += upgrade_cost
"}}]}}

